1	//! サブコマンドの本体。
2	
3	use crate::baseline::{self, SeriesStats, Source};
4	use crate::collector;
5	use crate::config::{BackendKind, Config, Watch};
6	use crate::detach;
7	use crate::diagnosis;
8	use crate::incident::{self, Evidence, Incident, format_time};
9	use crate::investigation;
10	use crate::known_set::{self, Classification, Roots};
11	use crate::lock;
12	use crate::logging;
13	use crate::notify::{self, Event};
14	use crate::paths::{Paths, create_private_dir};
15	use crate::probe::{self, ProbeRun, ProcessInfo};
16	use crate::process;
17	use crate::store::{Store, WatchState};
18	use crate::trigger::{self, Outcome, Variables};
19	use anyhow::{Context, Result, bail, ensure};
20	use chrono::Local;
21	use serde_json::Value;
22	use std::path::{Path, PathBuf};
23	use std::time::Duration;
24	
25	/// 事件の metrics.csv に載せる probe の回数（5 分間隔で 24 時間分）
26	const INCIDENT_HISTORY_RUNS: u32 = 288;
27	
28	fn now() -> i64 {
29	    Local::now().timestamp()
30	}
31	
32	/// スケジューラの起動はぴったり interval おきとは限らない。わずかに早い起動で
33	/// 1 周まるごと飛ばさないよう、interval の 1 割（最大 30 秒）の早まりを許す
34	fn is_due(last: Option<i64>, now: i64, interval: Duration) -> bool {
35	    let Some(last) = last else {
36	        return true;
37	    };
38	    let interval = interval.as_secs() as i64;
39	    now - last >= interval - (interval / 10).min(30)
40	}
41	
42	/// collector が失敗した取得の後は、snapshot_interval を待たずにこの間隔で取り直す
43	const SNAPSHOT_RETRY_INTERVAL: Duration = Duration::from_secs(30 * 60);
44	
45	/// スナップショットを取る時期か。最後の取得で全 collector が成功していれば snapshot_interval、
46	/// 失敗した collector があれば再試行の間隔（snapshot_interval が短ければそちら）を、
47	/// 最後の取得から空ける
48	fn is_snapshot_due(state: &WatchState, now: i64, interval: Duration) -> bool {
49	    let wait = if state.last_snapshot_complete == Some(true) {
50	        interval
51	    } else {
52	        interval.min(SNAPSHOT_RETRY_INTERVAL)
53	    };
54	    is_due(state.last_snapshot, now, wait)
55	}
56	
57	/// スナップショットを取り、取得履歴と比較基準に記録する
58	fn take_snapshot(store: &Store, watch: &Watch, now: i64) -> Result<Value> {
59	    let snapshot = collector::take_snapshot(&watch.baseline.snapshot_collectors, now);
60	    let keep = watch.baseline.keep_good_snapshots;
61	    store.record_snapshot(&watch.name, now, &snapshot, keep)?;
62	    Ok(snapshot)
63	}
64	
65	pub fn check(config: &Config, paths: &Paths, force: bool) -> Result<()> {
66	    if !lock::hold_until_exit(&paths.lock_file())? {
67	        log::info!("another check is running; skipping");
68	        return Ok(());
69	    }
70	    let mut store = Store::open(&paths.db_file())?;
71	    let mut failures = 0;
72	    for watch in &config.watches {
73	        // 1 つの watch の失敗で他の監視を止めない
74	        if let Err(error) = check_watch(&mut store, paths, watch, force, now()) {
75	            failures += 1;
76	            log::error!("watch {}: {error:#}", watch.name);
77	        }
78	    }
79	
80	    logging::prune(
81	        &paths.logs_dir,
82	        config.general.log_retention_days,
83	        Local::now().date_naive(),
84	    )?;
85	    incident::prune(
86	        &paths.incidents_dir,
87	        config.general.incident_retention_days,
88	        now(),
89	    )?;
90	    if failures > 0 {
91	        bail!("{failures} watch(es) failed");
92	    }
93	    Ok(())
94	}
95	
96	fn check_watch(
97	    store: &mut Store,
98	    paths: &Paths,
99	    watch: &Watch,
100	    force: bool,
101	    now: i64,
102	) -> Result<()> {
103	    let mut state = store.load_state(&watch.name)?;
104	    if !force && !is_due(state.last_probe, now, watch.interval) {
105	        log::debug!("{}: interval has not elapsed", watch.name);
106	        return Ok(());
107	    }
108	
109	    let run = probe::run(&watch.probe, now);
110	    let mut metrics = run.metrics();
111	    let classification = match &run.processes {
112	        Some(processes) => {
113	            let classification = classify_processes(store, paths, watch, processes, &metrics, now)?;
114	            metrics.extend(classification.metrics.clone());
115	            Some(classification)
116	        }
117	        None => None,
118	    };
119	    log_run(watch, &run, &metrics);
120	
121	    let stats = baseline::stats(store, &watch.name, &watch.baseline, now)?;
122	    let mut variables = metrics.clone();
123	    variables.extend(baseline::variables(&stats));
124	    let matched = trigger_matches(watch, &variables);
125	
126	    store.record_run(&watch.name, &run)?;
127	    if let Some(classification) = &classification {
128	        classification.record(store, &watch.name, now)?;
129	    }
130	    let retention = watch.baseline.metrics_retention.as_secs() as i64;
131	    store.prune_metrics(&watch.name, now - retention)?;
132	    state.last_probe = Some(now);
133	
134	    // 異常時の値でベースラインと last_known_good を汚さない
135	    let healthy = !matched && metrics["loss"] < 1.0;
136	    if healthy {
137	        baseline::update(store, &watch.name, &watch.baseline, &metrics, now)?;
138	        if is_snapshot_due(&state, now, watch.baseline.snapshot_interval)
139	            && !watch.baseline.snapshot_collectors.is_empty()
140	        {
141	            take_snapshot(store, watch, now)?;
142	        }
143	    }
144	
145	    let Some(trigger) = &watch.trigger else {
146	        store.save_state(&watch.name, &state)?;
147	        return Ok(());
148	    };
149	    let since = state.trigger.since;
150	    let outcome = trigger::advance(&mut state.trigger, matched, trigger, now);
151	    // 発火の処理で失敗しても二重に発火しないよう、先に状態を保存する
152	    store.save_state(&watch.name, &state)?;
153	    log::debug!("{}: trigger outcome {outcome:?}", watch.name);
154	
155	    match outcome {
156	        Outcome::Fired => {
157	            let since = state.trigger.since.unwrap_or(now);
158	            let reason = format!(
159	                "{} が {} 回連続で成立",
160	                trigger.when.source(),
161	                state.trigger.streak
162	            );
163	            let pending = classification
164	                .as_ref()
165	                .map(Classification::pending_identities)
166	                .unwrap_or_default();
167	            fire(store, paths, watch, &run, &stats, since, &reason, &pending)
168	        }
169	        Outcome::Suppressed => {
170	            log::info!("{}: in cooldown, not firing", watch.name);
171	            Ok(())
172	        }
173	        Outcome::Recovered if trigger.recover_notify => {
174	            write_recovery(paths, &watch.name, since.unwrap_or(now), now)
175	        }
176	        Outcome::Recovered => {
177	            log::info!("{}: recovered", watch.name);
178	            Ok(())
179	        }
180	        Outcome::Normal | Outcome::Pending => Ok(()),
181	    }
182	}
183	
184	fn log_run(watch: &Watch, run: &ProbeRun, metrics: &Variables) {
185	    log::info!("{}: {metrics:?}", watch.name);
186	    for result in &run.results {
187	        log::debug!(
188	            "{}: {} ok={} rtt_ms={:?} error={:?}",
189	            watch.name,
190	            result.target,
191	            result.ok,
192	            result.rtt_ms,
193	            result.error
194	        );
195	    }
196	}
197	
198	fn build_incident(
199	    store: &Store,
200	    paths: &Paths,
201	    watch: &Watch,
202	    run: &ProbeRun,
203	    stats: &[SeriesStats],
204	    since: i64,
205	    reason: &str,
206	) -> Result<Incident> {
207	    let created = now();
208	    let current = collector::take_snapshot(&watch.baseline.snapshot_collectors, created);
209	    let collectors: Vec<String> = watch
210	        .baseline
211	        .snapshot_collectors
212	        .iter()
213	        .map(|spec| spec.name())
214	        .collect();
215	    let last_good = store.last_known_good(&watch.name, &collectors)?;
216	    let history = store.recent_metrics(&watch.name, INCIDENT_HISTORY_RUNS)?;
217	    let evidence = Evidence {
218	        watch: &watch.name,
219	        reason,
220	        since,
221	        run,
222	        stats,
223	        history: &history,
224	        current: &current,
225	        last_good: last_good.as_ref(),
226	    };
227	    incident::create(&paths.incidents_dir, &evidence, created)
228	}
229	
230	fn register_investigation(paths: &Paths, watch: &str) -> Option<investigation::Registration> {
231	    let result =
232	        probe::enumerate().and_then(|processes| investigation::register(paths, watch, &processes));
233	    result.unwrap_or_else(|error| {
234	        log::warn!("{watch}: could not record the investigation: {error:#}");
235	        None
236	    })
237	}
238	
239	fn trigger_matches(watch: &Watch, variables: &Variables) -> bool {
240	    watch
241	        .trigger
242	        .as_ref()
243	        .is_some_and(|trigger| trigger.when.matches(variables))
244	}
245	
246	/// プロセスを既知の集合と照らして分類する。
247	///
248	/// 学習してよいのは正常な回だけ。正常かどうかは条件式の成否で決まるが、その式の変数は
249	/// 分類の結果に依存する。そこで、まず学習する前提で分類し、式が成立したら（異常なら）
250	/// 何も学習しない前提でやり直す。やり直すと pending が増えるだけなので、成立したままになる
251	fn classify_processes(
252	    store: &Store,
253	    paths: &Paths,
254	    watch: &Watch,
255	    processes: &[ProcessInfo],
256	    metrics: &Variables,
257	    now: i64,
258	) -> Result<Classification> {
259	    let roots = Roots::from_env();
260	    // kuda 自身と、実行中の調査プロセス（detach されていて親子ではたどれない）
261	    let mut excluded: Vec<_> = known_set::own_root(processes).into_iter().collect();
262	    excluded.extend(investigation::running(paths, processes));
263	    let classify =
264	        |learn| known_set::classify(store, watch, processes, &excluded, &roots, now, learn);
265	    let classification = classify(true)?;
266	    if classification.learned == 0 {
267	        return Ok(classification);
268	    }
269	    let mut variables = metrics.clone();
270	    variables.extend(classification.metrics.clone());
271	    if trigger_matches(watch, &variables) {
272	        return classify(false);
273	    }
274	    Ok(classification)
275	}
276	
277	#[allow(clippy::too_many_arguments)]
278	fn fire(
279	    store: &mut Store,
280	    paths: &Paths,
281	    watch: &Watch,
282	    run: &ProbeRun,
283	    stats: &[SeriesStats],
284	    since: i64,
285	    reason: &str,
286	    pending: &[String],
287	) -> Result<()> {
288	    let incident = build_incident(store, paths, watch, run, stats, since, reason)?;
289	    log::warn!(
290	        "{}: fired ({reason}); incident {}",
291	        watch.name,
292	        incident.dir.display()
293	    );
294	    // 事件に含めた分は報告済みにする。同じプロセスでは、クールダウンが明けても再発火しない
295	    store.mark_reported(&watch.name, pending)?;
296	    if watch.diagnose.is_some() {
297	        detach::spawn_diagnose(&watch.name, &incident.dir)?;
298	    }
299	    Ok(())
300	}
301	
302	fn write_recovery(paths: &Paths, watch: &str, since: i64, now: i64) -> Result<()> {
303	    let dir = paths.reports_dir.join(watch);
304	    create_private_dir(&dir)?;
305	    let stamp = Local::now().format("%Y%m%d-%H%M%S");
306	    let path = dir.join(format!("{stamp}-recovered.md"));
307	    let text = format!(
308	        "# 回復: {watch}\n\n- 発生開始: {}\n- 回復確認: {}\n",
309	        format_time(since),
310	        format_time(now)
311	    );
312	    std::fs::write(&path, text).with_context(|| format!("failed to write {}", path.display()))?;
313	    log::info!("{watch}: recovered; {}", path.display());
314	    Ok(())
315	}
316	
317	pub fn snapshot(config: &Config, paths: &Paths, force: bool, only: Option<&str>) -> Result<()> {
318	    if let Some(name) = only {
319	        config.watch(name)?;
320	    }
321	    let store = Store::open(&paths.db_file())?;
322	    let mut failed = 0;
323	    let selected = config
324	        .watches
325	        .iter()
326	        .filter(|watch| only.is_none_or(|name| name == watch.name));
327	    for watch in selected {
328	        let collectors = &watch.baseline.snapshot_collectors;
329	        if collectors.is_empty() {
330	            println!("{}: no snapshot_collectors configured", watch.name);
331	            continue;
332	        }
333	        // check のロックは取らない。check と並行してよいよう、スナップショットの記録以外は
334	        // 書かない。ここで読んだ状態を save_state で書き戻すと、収集中に check が保存した状態を巻き戻す
335	        let state = store.load_state(&watch.name)?;
336	        let now = now();
337	        if !force && !is_snapshot_due(&state, now, watch.baseline.snapshot_interval) {
338	            println!(
339	                "{}: not due yet (snapshot_interval, or the retry interval after a failure)",
340	                watch.name
341	            );
342	            continue;
343	        }
344	        let snapshot = take_snapshot(&store, watch, now)?;
345	        print_collectors(&watch.name, &snapshot);
346	        failed += collector::failed_collectors(&snapshot).len();
347	    }
348	    if failed > 0 {
349	        bail!("{failed} collector(s) failed");
350	    }
351	    Ok(())
352	}
353	
354	fn print_collectors(watch: &str, snapshot: &Value) {
355	    let collectors = snapshot["collectors"].as_object().into_iter().flatten();
356	    for (name, result) in collectors {
357	        match result["error"].as_str() {
358	            None => println!("{watch}: {name}: ok"),
359	            Some(error) => println!("{watch}: {name}: FAILED: {error}"),
360	        }
361	    }
362	}
363	
364	pub struct DiagnoseOptions {
365	    pub watch: String,
366	    pub dry_run: bool,
367	    pub backend: Option<String>,
368	    pub incident: Option<PathBuf>,
369	    pub notify: bool,
370	}
371	
372	pub fn diagnose(config: &Config, paths: &Paths, options: DiagnoseOptions) -> Result<()> {
373	    let watch = config.watch(&options.watch)?;
374	    let override_kind = options
375	        .backend
376	        .as_deref()
377	        .map(BackendKind::parse)
378	        .transpose()?;
379	
380	    let incident = match &options.incident {
381	        Some(dir) => incident::load(dir)?,
382	        None => manual_incident(paths, watch)?,
383	    };
384	    // 別の watch の事件を、この watch の設定やロックのまま調べない
385	    ensure!(
386	        incident.watch == watch.name,
387	        "incident {} belongs to watch {:?}, not {:?}",
388	        incident.dir.display(),
389	        incident.watch,
390	        watch.name
391	    );
392	    println!("incident: {}", incident.dir.display());
393	    if options.dry_run {
394	        return Ok(());
395	    }
396	
397	    let diagnose = watch
398	        .diagnose
399	        .as_ref()
400	        .with_context(|| format!("watch {} has no [watch.diagnose]", watch.name))?;
401	    let lock_path = paths
402	        .lock_dir
403	        .join(format!("kuda-diagnose-{}.lock", watch.name));
404	    if !lock::hold_until_exit(&lock_path)? {
405	        log::info!("{}: an investigation is already running", watch.name);
406	        println!("an investigation for {} is already running", watch.name);
407	        return Ok(());
408	    }
409	    // 調査の間だけ記録し、check のプロセス監視が調査プロセスを未知として数えないようにする
410	    let _registration = register_investigation(paths, &watch.name);
411	    let notify = options.notify && config.general.notify;
412	    if notify {
413	        notify::send(&Event::Started { watch: &watch.name });
414	    }
415	    let result = diagnosis::investigate(config, paths, diagnose, &incident, override_kind);
416	    if notify {
417	        let failed_report = diagnosis::report_path(paths, &incident).ok();
418	        notify::send(&match &result {
419	            Ok(report) => Event::Finished {
420	                watch: &watch.name,
421	                report,
422	            },
423	            Err(_) => Event::Failed {
424	                watch: &watch.name,
425	                report: failed_report.as_deref().filter(|path| path.is_file()),
426	            },
427	        });
428	    }
429	    let report = result?;
430	    log::info!("{}: report {}", watch.name, report.display());
431	    println!("report: {}", report.display());
432	    Ok(())
433	}
