213	    /// 版 1 のスキーマで `hist` (watch, series, bucket, bin, count) を記録した DB を開く
214	    #[cfg(test)]
215	    pub fn in_memory_v1(hist: &[(&str, &str, i64, i64, i64)]) -> Result<Self> {
216	        let conn = Connection::open_in_memory()?;
217	        conn.execute_batch(&format!("{SCHEMA_V1} PRAGMA user_version = 1;"))?;
218	        for row in hist {
219	            conn.execute(
220	                "INSERT INTO baseline_hist (watch, series, bucket, bin, count)
221	                 VALUES (?1, ?2, ?3, ?4, ?5)",
222	                params![row.0, row.1, row.2, row.3, row.4],
223	            )?;
224	        }
225	        Self::init(conn, Path::new(":memory:"))
226	    }
227	
228	    /// `path` はエラーメッセージに出すためのもの
229	    fn init(conn: Connection, path: &Path) -> Result<Self> {
230	        // 調査プロセスと次の check が同時に開いても待ち合わせで済むようにする
231	        conn.busy_timeout(Duration::from_secs(10))?;
232	        conn.pragma_update(None, "journal_mode", "WAL")?;
233	        let mut store = Self { conn };
234	        store.migrate(path)?;
235	        Ok(store)
236	    }
237	
238	    fn version(conn: &Connection) -> Result<usize> {
239	        let version: i64 = conn.pragma_query_value(None, "user_version", |row| row.get(0))?;
240	        Ok(version as usize)
241	    }
242	
243	    /// `user_version` の版から最新版まで 1 段ずつ上げる。
244	    /// 同時に開いた別プロセスと二重に適用しないよう、版の確認と適用を同じ書き込みトランザクションで行う。
245	    /// 新しい kuda が上げた DB は読み方が分からないので開かない（ダウングレードは非対応）
246	    fn migrate(&mut self, path: &Path) -> Result<()> {
247	        // 最新版なら書き込みロックを取らずに済ませる
248	        if Self::version(&self.conn)? == MIGRATIONS.len() {
249	            return Ok(());
250	        }
251	        loop {
252	            let tx = self
253	                .conn
254	                .transaction_with_behavior(TransactionBehavior::Immediate)?;
255	            let version = Self::version(&tx)?;
256	            if version == MIGRATIONS.len() {
257	                return Ok(());
258	            }
259	            let Some(migration) = MIGRATIONS.get(version) else {
260	                bail!(
261	                    "{} has schema version {version}, but this kuda supports up to {}. \
262	                     Update kuda, or move the database aside to start over",
263	                    path.display(),
264	                    MIGRATIONS.len()
265	                );
266	            };
267	            tx.execute_batch(migration).with_context(|| {
268	                format!(
269	                    "failed to migrate {} to schema version {}",
270	                    path.display(),
