1320	    #[test]
1321	    fn snapshot_does_not_roll_back_check_state() {
1322	        // 接続より先に宣言し、接続を閉じてから片付ける
1323	        let db = TempDb::new("snapshot-race");
1324	        let snapshot = db.open();
1325	        let check = db.open();
1326	
1327	        // snapshot が収集している間に check が状態を進めて保存し、その後 snapshot が
1328	        // 完了する。commands::snapshot は収集前に読んだ状態を書き戻さず、
1329	        // set_last_snapshot だけを呼ぶ
1330	        let mut checked = check.load_state("w").unwrap();
1331	        checked.last_probe = Some(10);
1332	        checked.trigger = TriggerState {
1333	            streak: 3,
