            Some(V1Hist {
                min_bucket: 0,
                max_bucket: 30,
                samples: 5
            })
        );
        assert_eq!(store.v1_hist("other").unwrap(), None);
    }

    #[test]
    fn v1_hist_is_adopted_once() {
        let store =
            Store::in_memory_v1(&[("w", "rtt", 9, 5, 2), ("other", "rtt", 9, 5, 1)]).unwrap();
        store.hist_add("w", "hour", "rtt", 9, 5).unwrap();
