645	    /// watch の識別キーと status を全件返す
646	    pub fn identity_statuses(&self, watch: &str) -> Result<HashMap<String, IdentityStatus>> {
647	        let mut statement = self
648	            .conn
649	            .prepare("SELECT identity, status FROM process_identities WHERE watch = ?1")?;
650	        let rows = statement.query_map(params![watch], |row| {
651	            Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
652	        })?;
653	        let mut statuses = HashMap::new();
654	        for row in rows {
655	            let (identity, status) = row?;
656	            statuses.insert(identity, IdentityStatus::parse(&status)?);
657	        }
658	        Ok(statuses)
659	    }
