685	    /// 指定した識別キーのうち pending のものを reported にする。
686	    /// 報告を始めた後に accept された known を巻き戻さないよう、pending だけを対象にする
687	    pub fn mark_reported(&mut self, watch: &str, identities: &[String]) -> Result<()> {
688	        let tx = self.conn.transaction()?;
689	        for identity in identities {
690	            tx.execute(
691	                "UPDATE process_identities SET status = 'reported'
692	                 WHERE watch = ?1 AND identity = ?2 AND status = 'pending'",
693	                params![watch, identity],
694	            )?;
695	        }
696	        tx.commit()?;
697	        Ok(())
698	    }
699	}
