438	            let available = crate::trigger::variables_for(crate::config::ProbeKind::Tcp);
439	            assert!(available.contains(&name.as_str()), "{name}");
440	        }
441	        assert!(variables.contains_key("baseline.rtt_p95"));
442	        assert_eq!(variables["baseline.loss_p95"], 0.0);
443	    }
444	
445	    #[test]
446	    fn negative_values_are_not_counted() {
447	        let store = Store::in_memory().unwrap();
448	        let config = config(1, AggregateBy::None);
449	        let values: Variables = [("value".to_string(), -1.0)].into_iter().collect();
450	        update(&store, "w", &config, &values, 0).unwrap();
451	        assert!(store.hist("w", "value", None).unwrap().is_empty());
452	    }
453	}
