368	    /// 今回見た識別キーを記録する。学習期間の起点もここで決まる
369	    pub fn record(&self, store: &mut Store, watch: &str, now: i64) -> Result<()> {
370	        store.start_learning(watch, now)?;
371	        store.observe_identities(watch, now, &self.seen)
372	    }
