1	//! LLM による調査。バックエンドの選択、フォールバック、レポートの保存。
2	//!
3	//! 使い魔は管の外へ無制限に出さない: 1 回の調査で試すのは主バックエンドと
4	//! fallback を 1 度ずつだけで、それぞれ `max_duration` で打ち切る。
5	
6	mod claude_code;
7	mod codex;
8	mod local;
9	
10	use crate::config::{BackendKind, Config, Diagnose};
11	use crate::incident::{Incident, format_time};
12	use crate::paths::{Paths, create_private_dir, is_safe_name};
13	use anyhow::{Context, Result, bail, ensure};
14	use std::fmt::Write as _;
15	use std::path::{Path, PathBuf};
16	use std::time::{Duration, Instant};
17	
18	pub struct Request<'a> {
19	    pub prompt: &'a str,
20	    pub incident_dir: &'a Path,
21	    /// バックエンドが一時ファイルを置くための、kuda が管理するディレクトリ。
22	    /// 事件ディレクトリは外から渡されうるので、そこには書かない
23	    pub work_dir: &'a Path,
24	    pub allowed_commands: &'a [String],
25	    pub timeout: Duration,
26	}
27	
28	pub trait Backend {
29	    /// 使える状態か確かめる。理由を添えて失敗を返す
30	    fn available(&self) -> Result<String, String>;
31	    /// 調査を実行し、レポート本文を返す
32	    fn run(&self, request: &Request) -> Result<String>;
33	}
34	
35	pub fn backend(config: &Config, kind: BackendKind) -> Result<Box<dyn Backend>> {
36	    let missing = || format!("backend {} is not configured", kind.name());
37	    Ok(match kind {
38	        BackendKind::ClaudeCode => {
39	            let settings = config.backends.claude_code.clone();
40	            Box::new(claude_code::ClaudeCode(settings.with_context(missing)?))
41	        }
42	        BackendKind::Codex => {
43	            let settings = config.backends.codex.clone();
44	            Box::new(codex::Codex(settings.with_context(missing)?))
45	        }
46	        BackendKind::Local => {
47	            let settings = config.backends.local.clone();
48	            Box::new(local::Local(settings.with_context(missing)?))
49	        }
50	    })
51	}
52	
53	pub fn expand_prompt(template: &str, incident: &Incident) -> String {
54	    template
55	        .replace("{{incident_dir}}", &incident.dir.display().to_string())
56	        .replace("{{watch}}", &incident.watch)
57	        .replace("{{os}}", std::env::consts::OS)
58	        .replace("{{since}}", &format_time(incident.since))
59	}
60	
61	struct Attempt {
62	    kind: BackendKind,
63	    elapsed: Duration,
64	    error: Option<String>,
65	}
66	
67	fn attempt_order(diagnose: &Diagnose, override_kind: Option<BackendKind>) -> Vec<BackendKind> {
68	    match override_kind {
69	        Some(kind) => vec![kind],
70	        None => std::iter::once(diagnose.backend)
71	            .chain(diagnose.fallback)
72	            .collect(),
73	    }
74	}
75	
76	fn run_backend(config: &Config, kind: BackendKind, request: &Request) -> Result<String> {
77	    let backend = backend(config, kind)?;
78	    if let Err(reason) = backend.available() {
79	        bail!("not available: {reason}");
80	    }
81	    backend.run(request)
82	}
83	
84	fn render_report(incident: &Incident, attempts: &[Attempt], body: &str) -> String {
85	    let mut text = format!("# 調査レポート: {}\n\n", incident.watch);
86	    let _ = writeln!(text, "- 事件: {}", incident.dir.display());
87	    let _ = writeln!(text, "- 発生開始: {}", format_time(incident.since));
88	    for attempt in attempts {
89	        let elapsed = attempt.elapsed.as_secs_f64();
90	        let outcome = match &attempt.error {
91	            None => "成功".to_string(),
92	            Some(error) => format!("失敗: {error}"),
93	        };
94	        let name = attempt.kind.name();
95	        let _ = writeln!(text, "- バックエンド {name}: {outcome}（{elapsed:.1} 秒）");
96	    }
97	    let _ = writeln!(text, "\n{body}");
98	    text
99	}
100	
101	/// レポートの保存先。watch と id が 1 つのパス要素でなければ reports の外を指しうるので拒む
102	pub fn report_path(paths: &Paths, incident: &Incident) -> Result<PathBuf> {
103	    ensure!(
104	        is_safe_name(&incident.watch) && is_safe_name(&incident.id),
105	        "unsafe incident name: watch {:?}, id {:?}",
106	        incident.watch,
107	        incident.id
108	    );
109	    Ok(paths
110	        .reports_dir
111	        .join(&incident.watch)
112	        .join(format!("{}.md", incident.id)))
113	}
114	
115	/// 調査を実行してレポートを保存し、そのパスを返す。全バックエンドが失敗しても
116	/// 失敗の記録をレポートとして残したうえでエラーを返す
117	pub fn investigate(
118	    config: &Config,
119	    paths: &Paths,
120	    diagnose: &Diagnose,
121	    incident: &Incident,
122	    override_kind: Option<BackendKind>,
123	) -> Result<PathBuf> {
124	    let path = report_path(paths, incident)?;
125	    let prompt_path = paths.config_dir.join(&diagnose.prompt_file);
126	    let template = std::fs::read_to_string(&prompt_path)
127	        .with_context(|| format!("failed to read {}", prompt_path.display()))?;
128	    let prompt = expand_prompt(&template, incident);
129	    let request = Request {
130	        prompt: &prompt,
131	        incident_dir: &incident.dir,
132	        work_dir: &paths.data_dir,
133	        allowed_commands: diagnose.allowed_commands.current(),
134	        timeout: diagnose.max_duration,
135	    };
136	
137	    let mut attempts = Vec::new();
138	    let mut body = None;
139	    for kind in attempt_order(diagnose, override_kind) {
140	        log::info!("investigating {} with {}", incident.id, kind.name());
141	        let started = Instant::now();
142	        let result = run_backend(config, kind, &request);
143	        let elapsed = started.elapsed();
144	        match result {
145	            Ok(text) => {
146	                attempts.push(Attempt {
147	                    kind,
148	                    elapsed,
149	                    error: None,
150	                });
151	                body = Some(text);
152	                break;
153	            }
154	            Err(error) => {
155	                log::warn!("backend {} failed: {error:#}", kind.name());
156	                attempts.push(Attempt {
157	                    kind,
158	                    elapsed,
159	                    error: Some(format!("{error:#}")),
160	                });
161	            }
162	        }
163	    }
164	
165	    create_private_dir(&paths.reports_dir.join(&incident.watch))?;
166	    let succeeded = body.is_some();
167	    let body = body.unwrap_or_else(|| "すべてのバックエンドが失敗しました。".to_string());
168	    std::fs::write(&path, render_report(incident, &attempts, &body))
169	        .with_context(|| format!("failed to write {}", path.display()))?;
170	    if !succeeded {
171	        bail!("all backends failed; see {}", path.display());
172	    }
173	    Ok(path)
174	}
