121	        // 消さない。列挙の直後に始まった調査の記録かもしれない
122	        assert!(registration.0.exists());
123	        assert_eq!(running(&paths, &[me(42)]).len(), 1);
124	        std::mem::forget(registration);
125	        std::fs::remove_dir_all(&paths.data_dir).unwrap();
126	    }
127	
128	    #[test]
129	    fn nothing_is_recorded_without_a_start_time() {
130	        let paths = paths("nostart");
131	        let mut unknown = me(1);
132	        unknown.started = None;
133	        assert!(register(&paths, "w", &[unknown]).unwrap().is_none());
134	        std::fs::remove_dir_all(&paths.data_dir).unwrap();
135	    }
