    fn surfaces_errors_from_the_result() {
        let stdout = r#"{"type":"result","subtype":"error_max_turns","is_error":true,"result":""}"#;
        let error = parse_output(stdout).unwrap_err().to_string();
        assert!(error.contains("error_max_turns"));
    }

