/// 何も学習しない前提でやり直す。やり直すと pending が増えるだけなので、成立したままになる。
/// `learn` が false なら最初から学習しない（手動の調査用）
fn classify_processes(
    store: &Store,
    paths: &Paths,
    watch: &Watch,
    spec: &ProcessSpec,
    run: &ProbeRun,
    now: i64,
    learn: bool,
