1	//! 待ち受けている TCP/UDP のポートと、それを持つプロセス。
2	//!
3	//! 外部コマンド（netstat、ss）は使わない。Windows は IP Helper、Linux は /proc を読む。
4	
5	use crate::known_set;
6	use crate::os::Os;
7	use crate::probe::{self, ProcessInfo};
8	use anyhow::Result;
9	use serde_json::{Map, Value, json};
10	use std::collections::{BTreeMap, BTreeSet, HashMap};
11	use std::net::IpAddr;
12	
13	/// 待ち受けの 1 件。UDP は接続を持たないので、束縛されたソケットを待ち受けとみなす
14	#[derive(Debug, Clone, PartialEq, Eq)]
15	struct Listener {
16	    proto: &'static str,
17	    addr: IpAddr,
18	    port: u16,
19	    /// 持ち主。Linux では 1 つのソケットを複数のプロセスが持ちうる（ソケット起動など）。
20	    /// 空なら持ち主を引けなかった
21	    pids: Vec<u32>,
22	}
23	
24	impl Listener {
25	    /// `tcp:0.0.0.0:80`、`udp:[::]:53`。IPv6 は括弧で囲み、ポートと区切れるようにする
26	    fn key(&self) -> String {
27	        match self.addr {
28	            IpAddr::V4(addr) => format!("{}:{addr}:{}", self.proto, self.port),
29	            IpAddr::V6(addr) => format!("{}:[{addr}]:{}", self.proto, self.port),
30	        }
31	    }
32	}
33	
34	pub fn collect() -> Result<Value> {
35	    let listeners = imp::listeners()?;
36	    // 持ち主の識別は processes collector と同じ規則。列挙できなくてもポートの一覧は返す
37	    let processes = probe::enumerate().unwrap_or_default();
38	    Ok(render(&listeners, &identities(Os::current(), &processes)))
39	}
40	
41	fn identities(os: Os, processes: &[ProcessInfo]) -> HashMap<u32, String> {
42	    processes
43	        .iter()
44	        .filter_map(|p| Some((p.pid, known_set::identify(os, p)?.key)))
45	        .collect()
46	}
47	
48	/// `{ "<proto:addr:port>": { "processes": ["<identity>", ...] } }`。
49	/// PID は毎回変わるので入れず、持ち主は識別キーで示す
50	fn render(listeners: &[Listener], identities: &HashMap<u32, String>) -> Value {
51	    let mut owners: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
52	    for listener in listeners {
53	        let owner = listener.pid.and_then(|pid| identities.get(&pid));
54	        let entry = owners.entry(listener.key()).or_default();
55	        // 持ち主が分からない（権限が足りない、列挙の合間に終わった）ことも差分で見えるようにする
56	        entry.insert(owner.cloned().unwrap_or_else(|| "unknown".to_string()));
