108	    /// 8 バイト境界の領域に確保するのは、表の先頭が u32 の件数で、行が u32 だけでできているため
109	    fn table(fetch: impl Fn(*mut c_void, &mut u32) -> u32) -> Result<Vec<u64>> {
110	        let mut buffer: Vec<u64> = vec![0; 512];
111	        for _ in 0..4 {
112	            let mut size = (buffer.len() * 8) as u32;
113	            let status = fetch(buffer.as_mut_ptr().cast::<c_void>(), &mut size);
114	            if status == NO_ERROR.0 {
115	                return Ok(buffer);
116	            }
117	            if status != ERROR_INSUFFICIENT_BUFFER.0 {
118	                bail!("GetExtended*Table failed: {status}");
119	            }
120	            // 件数の増加に備えて余裕を持つ
121	            buffer = vec![0; (size as usize + 1024).div_ceil(8)];
122	        }
