fn parses_the_local_port_range() {
    assert_eq!(parse_port_range("32768\t60999\n"), Some(32768..=60999));
    assert_eq!(parse_port_range("60999 32768"), None);
    assert_eq!(parse_port_range("garbage"), None);
}

