            .iter()
            .filter_map(|(name, result)| match result {
                CollectorResult::Ok(data) => Some((
                    name.clone(),
                    collector::KnownGoodEntry {
                        taken_at: snapshot.taken_at,
                        data: data.clone(),
                    },
                )),
                CollectorResult::Failed(_) => None,
            })
            .collect();
        KnownGood { collectors }
    }

