/// Markdown の中で文字どおりに見せる。改行は空白にし、表を崩す `|` と、リンクや画像
/// （開いただけで外部を読みに行く）になる記号を `\` で逃がす。`\` 自身も逃がさないと、
/// `a\|b` の `\` が `|` の逃がしを打ち消して表が崩れる
fn cell(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        match c {
            '\r' | '\n' => out.push(' '),
            '\\' | '|' | '[' | ']' | '<' | '>' | '!' | '`' => {
                out.push('\\');
                out.push(c);
            }
            _ => out.push(c),
        }
    }
    out
}

